        if int(strict.get("required_rework_count") or 0) > 0 or review.get("rework_targets"):
            risks["open_rework_targets"].append({"paper_id": paper_id, "count": strict.get("required_rework_count")})

        for index, record in enumerate(activity.get("activity_records") or [], start=1):
            if not isinstance(record, dict):
                continue
            counters["activity_records"] += 1
            endpoint = str(record.get("endpoint") or "").strip()
            raw_value = str(record.get("raw_value") or "").strip()
            raw_unit = str(record.get("raw_unit") or "").strip()
            species = target_species(record)
            locator = record.get("source_locator") or record.get("source_locators")
            if endpoint.lower() in GENERIC_ENDPOINTS:
                risks["generic_activity_endpoint"].append({"paper_id": paper_id, "row": index, "endpoint": endpoint, "raw_value": raw_value})
            if endpoint.upper() in MIC_LIKE and not raw_unit:
                risks["mic_like_missing_unit"].append({"paper_id": paper_id, "row": index, "endpoint": endpoint, "raw_value": raw_value})
            if suspicious_species(species):
                risks["suspicious_target_species"].append({"paper_id": paper_id, "row": index, "endpoint": endpoint, "species": species[:160]})
            if not raw_value or not has_locator(locator):
                risks["activity_core_or_locator_gap"].append({"paper_id": paper_id, "row": index, "endpoint": endpoint})

        for index, claim in enumerate(mechanism.get("mechanism_claims") or [], start=1):
            if not isinstance(claim, dict):
                continue
            counters["mechanism_claims"] += 1
            evidence_class = str(claim.get("evidence_class") or claim.get("mechanism_evidence_class") or "")
            if not claim.get("claim_id"):
                risks["mechanism_missing_claim_id"].append({"paper_id": paper_id, "claim_index": index})
            if not (claim.get("claim_text") or claim.get("summary")):
                risks["mechanism_missing_claim_text"].append({"paper_id": paper_id, "claim_index": index})
            if not has_locator(claim.get("source_locator") or claim.get("source_locators")):
                risks["mechanism_locator_gap"].append({"paper_id": paper_id, "claim_index": index})
            if evidence_class == "direct_mechanism" and not (claim.get("direct_assay_types") or claim.get("direct_assay_type")):
                risks["direct_mechanism_without_assay"].append({"paper_id": paper_id, "claim_index": index})

    issue_counts = issue_log_counts(args.issues)
    for key in ("accelerator_auto_closed", "fallback_or_deterministic_event", "issue_log_parse_error"):
        if issue_counts.get(key):
            risks[key].append({"count": issue_counts[key]})

    risk_counts: dict[str, int] = {}
    for key, value in sorted(risks.items()):
        if len(value) == 1 and isinstance(value[0], dict) and isinstance(value[0].get("count"), int):
            risk_counts[key] = int(value[0]["count"])
        else:
            risk_counts[key] = len(value)

    summary = {
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
        "manifest": str(args.manifest),
        "paper_count": len(paper_ids),
        "review_status": dict(review_status),
        "counts": dict(counters),
        "issue_log_counts": dict(issue_counts),
        "risk_counts": risk_counts,
        "risk_examples": {key: value[:5] for key, value in sorted(risks.items())},
        "publication_grade_pass": not risks,
    }
    text = json.dumps(summary, ensure_ascii=False, indent=2)
    if args.json_out:
        args.json_out.write_text(text + "\n")
    print(text)
    return 0 if args.allow_risk or not risks else 2


